def beam_search(start={{start_state}}, expand={{expand_fn}}, score={{score_fn}}, k={{beam_width}}, steps={{max_steps}}):
    beams = [(0.0, start)]
    for _ in range(steps):
        cands = []
        for s, state in beams:
            for next_state in expand(state):
                cands.append((s + score(state, next_state), next_state))
        if not cands: break
        beams = sorted(cands, key=lambda x: -x[0])[:k]
    return beams
